//
// A concurrent same-key transaction may win the insert race and then roll
// back (e.g. on a storage failure), leaving no record; in that case the
// FOR UPDATE lookup raises serialization failure 40001 / no rows and the
// claim is retried so the caller can take ownership of a fresh record.
func claimIdempotency(ctx context.Context, q pgx.Tx, tenantID, operation, key, requestHash string) (idempotencyOutcome, operationResult, error) {
	for attempt := 0; attempt < 3; attempt++ {
		var insertedID int64
		err := q.QueryRow(ctx, `
			INSERT INTO idempotency_records
			    (tenant_id, operation, idempotency_key, request_hash, status_code, response_body)
			VALUES ($1, $2, $3, $4, 0, '{}'::jsonb)
			ON CONFLICT (tenant_id, operation, idempotency_key) DO NOTHING
			RETURNING id`,
			tenantID, operation, key, requestHash,
		).Scan(&insertedID)
		if err == nil {
			return idempotencyClaimed, operationResult{}, nil
		}
		if !errors.Is(err, pgx.ErrNoRows) {
			return 0, operationResult{}, err
		}

		var storedHash string
		var storedStatus int
		var storedBody []byte
		err = q.QueryRow(ctx, `
			SELECT request_hash, status_code, response_body
			FROM idempotency_records
			WHERE tenant_id = $1 AND operation = $2 AND idempotency_key = $3
			FOR UPDATE`,
			tenantID, operation, key,
		).Scan(&storedHash, &storedStatus, &storedBody)
		switch {
		case err == nil:
			if storedHash != requestHash {
				return idempotencyMismatch, operationResult{
					status: http.StatusConflict,
					body:   []byte(`{"error":"Idempotency-Key was reused with a different request"}`),
				}, nil
			}
			// Same request replay: always surface as HTTP 200 with the original result.
			return idempotencyReplay, operationResult{status: http.StatusOK, body: storedBody}, nil
		case errors.Is(err, pgx.ErrNoRows) || isSerializationFailure(err):
			continue // the winner transaction vanished; try to claim again
		default:
			return 0, operationResult{}, err
		}
	}
	return 0, operationResult{}, errors.New("could not claim idempotency record")
}

func isSerializationFailure(err error) bool {
	var pgErr *pgconn.PgError
	return errors.As(err, &pgErr) && pgErr.Code == "40001"
}

