	}
	body := fmt.Sprintf(`{"reservationId":"r2","amount":1,"expiresAt":%q}`, now.Add(time.Hour).Format(time.RFC3339Nano))
	first := e.createReservationRaw("tr", "pr", "kfail", body)
	if first.Code != http.StatusConflict {
