	}
	if !strings.Contains(replay.Body.String(), "insufficient") {
		t.Fatalf("replay must carry original result, got %s", replay.Body.String())
	}
	if n := e.queryInt(`SELECT count(*) FROM reservations WHERE reservation_id='r2'`); n != 0 {
