	var resp reservationResponse
	err = tx.QueryRow(ctx, `
		SELECT tenant_id, pool_id, reservation_id, amount, status, expires_at, created_at, updated_at
		FROM reservations
		WHERE tenant_id = $1 AND pool_id = $2 AND reservation_id = $3`,
