	).Scan(&resp.TenantID, &resp.PoolID, &resp.ReservationID, &resp.Amount, &resp.Status, &resp.ExpiresAt, &resp.CreatedAt, &resp.UpdatedAt)
	if errors.Is(err, pgx.ErrNoRows) {
